-- VIEW: stock_analysis.vw_analysis_result_summary_20d
-- Generated by scripts/db/export_postgres_ddl.py

SET search_path = "stock_analysis", pg_catalog;

CREATE OR REPLACE VIEW "stock_analysis"."vw_analysis_result_summary_20d" AS
 SELECT analysis_result_id,
    hypothesis_name,
    count(*) AS sample_count,
    sum(
        CASE
            WHEN return_20d_pct > 0::numeric THEN 1
            ELSE 0
        END) AS win_count_20d,
    sum(
        CASE
            WHEN return_20d_pct < 0::numeric THEN 1
            ELSE 0
        END) AS lose_count_20d,
    sum(
        CASE
            WHEN return_20d_pct = 0::numeric THEN 1
            ELSE 0
        END) AS draw_count_20d,
    round(sum(
        CASE
            WHEN return_20d_pct > 0::numeric THEN 1
            ELSE 0
        END)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 4) AS win_rate_20d_pct,
    round(sum(
        CASE
            WHEN return_20d_pct < 0::numeric THEN 1
            ELSE 0
        END)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 4) AS lose_rate_20d_pct,
    round(avg(return_20d_pct), 4) AS avg_return_20d_pct,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (return_20d_pct::double precision))::numeric, 4) AS median_return_20d_pct,
    round(percentile_cont(0.10::double precision) WITHIN GROUP (ORDER BY (return_20d_pct::double precision))::numeric, 4) AS p10_return_20d_pct,
    round(percentile_cont(0.25::double precision) WITHIN GROUP (ORDER BY (return_20d_pct::double precision))::numeric, 4) AS p25_return_20d_pct,
    round(percentile_cont(0.75::double precision) WITHIN GROUP (ORDER BY (return_20d_pct::double precision))::numeric, 4) AS p75_return_20d_pct,
    round(percentile_cont(0.90::double precision) WITHIN GROUP (ORDER BY (return_20d_pct::double precision))::numeric, 4) AS p90_return_20d_pct,
    min(return_20d_pct) AS min_return_20d_pct,
    max(return_20d_pct) AS max_return_20d_pct,
    count(DISTINCT ticker) AS ticker_count,
    count(DISTINCT trade_date) AS signal_date_count
   FROM analysis_result_detail ard
  WHERE return_20d_pct IS NOT NULL
  GROUP BY analysis_result_id, hypothesis_name;
